INSERT INTO public.email_template_config (id, tenant_id, name, template_type, subject_template, body_html, body_text, is_active, is_default_for_type, created_by, created_at, updated_at) VALUES
	(1, 1, 'Monthly Statement', 'STATEMENT', 'Your {{month}} Performance Statement - {{merchant_name}}', '<!DOCTYPE html><html><head><style>body{font-family:Helvetica,Arial,sans-serif;line-height:1.6;color:#333;background:#f9fafb;margin:0;padding:0}.container{max-width:600px;margin:0 auto;background:#fff;border-radius:8px;overflow:hidden;box-shadow:0 4px 6px rgba(0,0,0,.05)}.header{background:#0f172a;color:#fff;padding:30px;text-align:center}.header h1{margin:0;font-size:24px}.content{padding:40px 30px}.greeting{font-size:18px;color:#1e293b;margin-bottom:20px}.card{background:#f1f5f9;border-radius:8px;padding:20px;margin-bottom:20px;border:1px solid #e2e8f0}.stats{display:flex;gap:20px;margin:20px 0}.stat{flex:1;text-align:center;padding:15px;background:#fff;border-radius:8px;border:1px solid #e2e8f0}.stat-value{font-size:22px;font-weight:700;color:#0f172a}.stat-label{font-size:12px;color:#64748b;text-transform:uppercase}.footer{background:#f8fafc;padding:20px;text-align:center;font-size:12px;color:#94a3b8;border-top:1px solid #e2e8f0}</style></head><body><div class="container"><div class="header"><h1>{{tenant_name}}</h1></div><div class="content"><div class="greeting">Dear {{contact_name}},</div><p>Your performance statement for <strong>{{month}}</strong> is now available.</p><div class="card"><div style="font-size:14px;color:#64748b;text-transform:uppercase;font-weight:600;margin-bottom:10px">Performance Summary</div><div class="stats"><div class="stat"><div class="stat-value">{{total_count}}</div><div class="stat-label">Transactions</div></div><div class="stat"><div class="stat-value">{{total_volume}}</div><div class="stat-label">Volume</div></div><div class="stat"><div class="stat-value">{{total_msf}}</div><div class="stat-label">MSF Revenue</div></div></div></div><p style="color:#64748b">Please find the detailed PDF report attached to this email.</p></div><div class="footer">&copy; 2026 {{tenant_name}}. All rights reserved.<br>This is an automated message.</div></div></body></html>', NULL, true, true, NULL, '2026-11-12 11:15:30.495264', NULL),
	(2, 1, 'Welcome Email', 'WELCOME', 'Welcome to {{tenant_name}} - {{merchant_name}}', '<!DOCTYPE html><html><head><style>body{font-family:Helvetica,Arial,sans-serif;line-height:1.6;color:#333;background:#f9fafb;margin:0;padding:0}.container{max-width:600px;margin:0 auto;background:#fff;border-radius:8px;overflow:hidden;box-shadow:0 4px 6px rgba(0,0,0,.05)}.header{background:linear-gradient(135deg,#2563eb,#7c3aed);color:#fff;padding:40px;text-align:center}.header h1{margin:0;font-size:28px}.content{padding:40px 30px}.footer{background:#f8fafc;padding:20px;text-align:center;font-size:12px;color:#94a3b8}</style></head><body><div class="container"><div class="header"><h1>Welcome!</h1></div><div class="content"><h2>Hello {{contact_name}},</h2><p>Welcome to <strong>{{tenant_name}}</strong>! We are excited to have <strong>{{merchant_name}}</strong> onboard.</p><p>Your Merchant ID is <strong>{{mid}}</strong>.</p><p>You can view your transaction data, performance analytics, and monthly statements through our portal.</p></div><div class="footer">&copy; 2026 {{tenant_name}}. All rights reserved.</div></div></body></html>', NULL, true, true, NULL, '2026-11-12 11:15:30.495264', NULL),
	(3, 1, 'Dormancy Alert', 'ALERT', 'Action Required: {{merchant_name}} - No recent transactions', '<!DOCTYPE html><html><head><style>body{font-family:Helvetica,Arial,sans-serif;line-height:1.6;color:#333;background:#f9fafb;margin:0;padding:0}.container{max-width:600px;margin:0 auto;background:#fff;border-radius:8px;overflow:hidden}.header{background:#dc2626;color:#fff;padding:30px;text-align:center}.content{padding:40px 30px}.alert-box{background:#fef2f2;border:1px solid #fecaca;border-radius:8px;padding:20px;margin:20px 0}.footer{background:#f8fafc;padding:20px;text-align:center;font-size:12px;color:#94a3b8}</style></head><body><div class="container"><div class="header"><h1>⚠ Activity Alert</h1></div><div class="content"><p>Dear Team,</p><div class="alert-box"><strong>{{merchant_name}}</strong> (MID: {{mid}}) has not processed transactions in <strong>{{days_since_last_txn}} days</strong>.</div><p>Location: {{city}}<br>Status: {{merchant_status}}<br>Stores: {{store_count}} | Terminals: {{terminal_count}}</p><p>Please follow up to ensure the merchant is still active.</p></div><div class="footer">&copy; 2026 {{tenant_name}}</div></div></body></html>', NULL, true, true, NULL, '2026-11-12 11:15:30.495264', NULL);
